#!/usr/bin/env python3
"""Bounded whole/ROI MagicShield panels paired by declared absolute ticks."""
import argparse,json,re,struct
from pathlib import Path
from PIL import Image,ImageDraw
from speed_profile_contract import sha

def run(native,metal,out):
 out.mkdir(parents=True,exist_ok=False);n=json.loads((native/'manifest.json').read_text());m=json.loads((metal/'manifest.json').read_text());assert m['status']=='pass'and len(m['frames'])==170 and m['sample_simulation_ticks']==list(range(1,171));pairs=[];selected=[r for r in n['rows']if r['image']];roi=(275,210,365,340);crop=Image.new('RGB',(180,len(selected)*155));detail=Image.new('RGB',(720,len(selected)*545));whole_paths=[]
 for row,r in enumerate(selected):
  t=r['tick'];f=m['frames'][t-1];paths=[Path(r['image']),Path(f['path'])];hashes=[r['image_sha256'],f['sha256']];assert[sha(p.read_bytes())for p in paths]==hashes;images=[Image.open(p).convert('RGB')for p in paths];boxes=[im.getbbox()for im in images];assert all(b is None or b[0]>0 and b[1]>0 and b[2]<640 and b[3]<480 for b in boxes);whole=Image.new('RGB',(1280,505))
  for col,(im,label)in enumerate(zip(images,('Original','Actual Metal'))):
   whole.paste(im,(col*640,25));ImageDraw.Draw(whole).text((col*640+4,5),f'{label} MagicShield {n["variant_name"]} tick{t}',fill='white');p=im.crop(roi);crop.paste(p,(col*90,row*155+25));ImageDraw.Draw(crop).text((col*90+2,row*155+5),f'{label} {t}',fill='white');detail.paste(p.resize((360,520),Image.Resampling.NEAREST),(col*360,row*545+25));ImageDraw.Draw(detail).text((col*360+2,row*545+5),f'{label} {t} 4xnearest',fill='white')
  file=out/f'whole-{t:03d}.png';whole.save(file);whole_paths.append(dict(path=str(file),sha256=sha(file.read_bytes())));pairs.append(dict(tick=t,images=list(map(str,paths)),sha256=hashes,visible_bbox=boxes,owner_phase=r['owner_phase'],countdown=r['owner_countdown'],invoker_resistance=r['invoker_factor'],native_draws=len(r['draws']),flags=r['flags']))
 crop.save(out/'fixed-crop.png');detail.save(out/'nearest4x-details.png');errors=[];fields=0;maximum=0
 for tick,phase,countdown,angle,x,y,z,resistance,draws,rng in re.findall(r'\[magicshield-phase\] tick=(\d+) phase=(\d+) countdown=(-?\d+) angle=([0-9.eE+-]+) scale=([0-9.eE+-]+),([0-9.eE+-]+),([0-9.eE+-]+) resistance=([0-9.eE+-]+) draws=(\d+) rng=(\d+)',(metal/'run.log').read_text()):
  t=int(tick);r=n['rows'][t-1];v=struct.unpack_from('<4f',bytes.fromhex(r['custom_state_hex']));d=max(abs(a-b)for a,b in zip(v,map(float,(angle,x,y,z))));maximum=max(maximum,d);fields+=8
  if int(phase)!=r['owner_phase']or int(countdown)!=r['owner_countdown']or float(resistance)!=r['invoker_factor']or int(draws)!=len(r['draws'])or d>2e-6:errors.append(dict(tick=t,error=d))
 report=dict(status='awaiting_independent_review',accepted=False,type_id='0xad92bc1b',variant_name=n['variant_name'],binary_sha256=m['binary_sha256'],pairs=pairs,whole_panels=whole_paths,panel_hashes={str(out/name):sha((out/name).read_bytes())for name in('fixed-crop.png','nearest4x-details.png')},actual_source_fields=fields,max_source_state_error=maximum,state_errors=errors,native_manifest_sha256=sha((native/'manifest.json').read_bytes()),metal_manifest_sha256=sha((metal/'manifest.json').read_bytes()),configuration=m['scenario'],appearance_fitted=False,scope='Full genuine existing named variant/Acolyte publicSetSpell and original MagicShield owner/controller/whole object0sphere690triangles+object1quad/normalARGB4444 raster vs actualMetal170. Exact unknown-name constructor storage0 basic branch,10rising glows, actual owner151death/blanktails. Phase2 real Fire Flash minimum50→magic resistance0.5; Aura0 control; clears126. Source retains actual masked scale<=0 sphere rejection from136 and zero-scale MATRIX-ring draws. FixedROI275,210,365,340/4xnearest display only, all nonempty bounds interior640x480, camera320/320/source0/0/16. Natural three absent variant names/tier1/2, allocator state, spell scheduler/gameplay/actor motion/audio/device/exactpixels remain open; sampling/fringe/color residuals are not equality.');(out/'manifest.json').write_text(json.dumps(report,indent=2)+'\n');print(report['status'],len(pairs),fields,maximum,len(errors));return report
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--native',type=Path,required=True);p.add_argument('--metal',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();run(a.native,a.metal,a.output)
